-- Synthetic rollback-only lesson records; no real files, accounts or existing rows changed.
begin;
create temp table lesson_results(name text primary key);
grant select,insert on lesson_results to authenticated,anon;
create function pg_temp.ok(value boolean,label text) returns void language plpgsql as $$ begin if value is distinct from true then raise exception 'FAILED %',label; end if;insert into pg_temp.lesson_results values(label); end $$;
create function pg_temp.denied(statement text,code text,label text) returns void language plpgsql as $$ declare caught text;begin begin execute statement;exception when others then get stacked diagnostics caught=returned_sqlstate;end;if caught is distinct from code then raise exception 'FAILED % expected % got %',label,code,caught;end if;insert into pg_temp.lesson_results values(label);end $$;
create function pg_temp.claim(n integer) returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('iss','https://gmvouqgjbtbkbhrdruzu.supabase.co/auth/v1','aud','authenticated','role','authenticated','sub','10000000-0000-0000-0000-'||lpad(n::text,12,'0'))::text,true)::text::void$$;
select pg_temp.ok(exists(select 1 from public.lesson_segments s join public.lessons l on l.id=s.lesson_id where l.id='50000000-0000-0000-0000-000000000001' and s.title=l.title and s.status=l.status),'existing Supabase block lesson has a real delivery part');
select pg_temp.ok(exists(select 1 from public.lesson_segment_progress s join public.lesson_progress p on p.lesson_id=s.lesson_id and p.offering_id=s.offering_id and p.user_id=s.user_id where s.lesson_id='50000000-0000-0000-0000-000000000001' and s.status=p.status and s.started_at=p.started_at),'existing offering progress is carried over without invented completion');
select set_config('lessons.course',gen_random_uuid()::text,true);
select set_config('lessons.offering',gen_random_uuid()::text,true);
insert into public.courses(id,organization_id,title,slug,status,created_by) values(current_setting('lessons.course')::uuid,'20000000-0000-0000-0000-000000000001','Synthetic lessons','synthetic-'||gen_random_uuid(),'published','10000000-0000-0000-0000-000000000001');
insert into public.course_staff(course_id,user_id,role) values(current_setting('lessons.course')::uuid,'10000000-0000-0000-0000-000000000002','instructor'),(current_setting('lessons.course')::uuid,'10000000-0000-0000-0000-000000000004','editor');
insert into public.course_offerings(id,course_id,name,status) values(current_setting('lessons.offering')::uuid,current_setting('lessons.course')::uuid,'Synthetic lesson offering','active');
insert into public.enrollments(offering_id,user_id,status) values(current_setting('lessons.offering')::uuid,'10000000-0000-0000-0000-000000000005','active'),(current_setting('lessons.offering')::uuid,'10000000-0000-0000-0000-000000000006','active');
set local role authenticated;
select pg_temp.claim(2);
select set_config('lessons.module',public.edit_learning_content(current_setting('lessons.course')::uuid,'create_module',null,null,null,'{"title":"Module A"}')::text,true);
select pg_temp.ok((select position=0 from public.course_modules where id=current_setting('lessons.module')::uuid),'teacher creates module');
select set_config('lessons.lesson',public.edit_learning_content(current_setting('lessons.course')::uuid,'create_lesson',null,current_setting('lessons.module')::uuid,null,'{"title":"Lesson A"}')::text,true);
select pg_temp.ok((select status='draft' from public.lessons where id=current_setting('lessons.lesson')::uuid),'lesson starts as draft');
select set_config('lessons.part',public.edit_learning_content(current_setting('lessons.course')::uuid,'create_segment',null,current_setting('lessons.lesson')::uuid,null,'{"title":"Part A"}')::text,true);
select set_config('lessons.part2',public.edit_learning_content(current_setting('lessons.course')::uuid,'create_segment',null,current_setting('lessons.lesson')::uuid,null,'{"title":"Part B"}')::text,true);
select set_config('lessons.stamp',(select updated_at::text from public.lesson_segments where id=current_setting('lessons.part')::uuid),true);
select pg_temp.denied($s$select public.edit_learning_content(current_setting('lessons.course')::uuid,'edit_segment',current_setting('lessons.part')::uuid,null,current_setting('lessons.stamp')::timestamptz,'{"title":"Part","description":"","status":"published"}')$s$,'23514','empty part cannot publish');
select public.edit_learning_content(current_setting('lessons.course')::uuid,'edit_segment',current_setting('lessons.part')::uuid,null,current_setting('lessons.stamp')::timestamptz,'{"title":"Part A","description":"Notes A","status":"published","video_url":"https://example.invalid/video.mp4"}');
select pg_temp.ok((select description='Notes A' and status='published' from public.lesson_segments where id=current_setting('lessons.part')::uuid),'teacher edits and publishes part');
select public.edit_learning_content(current_setting('lessons.course')::uuid,'edit_lesson',current_setting('lessons.lesson')::uuid,null,(select updated_at from public.lessons where id=current_setting('lessons.lesson')::uuid),'{"title":"Lesson A","description":"Lesson overview","status":"published"}');

reset role;
create temp table original_lessons as select * from public.lessons;
create temp table original_progress as select * from public.lesson_progress;
set local role authenticated;
select pg_temp.claim(2);
select public.edit_learning_content(current_setting('lessons.course')::uuid,'edit_module_details',current_setting('lessons.module')::uuid,null,(select updated_at from public.course_modules where id=current_setting('lessons.module')::uuid),'{"title":"Ohm law","group_type":"Special Review","chapter_number":37,"summary":"Short summary","description":"<p>Long <strong>description</strong></p>"}');
select pg_temp.ok((select title='Ohm law' and group_type='Special Review' and chapter_number=37 and summary='Short summary' and description='<p>Long <strong>description</strong></p>' from public.course_modules where id=current_setting('lessons.module')::uuid),'complete custom chapter metadata persists');
select set_config('chapters.second',public.edit_learning_content(current_setting('lessons.course')::uuid,'create_module',null,null,null,'{"title":"Second"}')::text,true);
select pg_temp.ok((select chapter_number=1 from public.course_modules where id=current_setting('chapters.second')::uuid),'new module has independent default number');
select public.edit_learning_content(current_setting('lessons.course')::uuid,'reorder_modules',null,null,null,jsonb_build_object('items',(select jsonb_agg(jsonb_build_object('id',id,'updated_at',updated_at) order by position desc) from public.course_modules where course_id=current_setting('lessons.course')::uuid)));
select pg_temp.ok((select chapter_number=37 and position=1 from public.course_modules where id=current_setting('lessons.module')::uuid),'reordering preserves selected number');
select pg_temp.denied($s$select public.edit_learning_content(current_setting('lessons.course')::uuid,'edit_module_details',current_setting('lessons.module')::uuid,null,now()-interval '1 second','{"title":"Name","group_type":"Unit","chapter_number":1}')$s$,'PT409','stale metadata denied');
select pg_temp.denied($s$select public.edit_learning_content(current_setting('lessons.course')::uuid,'edit_module_details',current_setting('lessons.module')::uuid,null,(select updated_at from public.course_modules where id=current_setting('lessons.module')::uuid),'{"title":"Name","group_type":"Unit","chapter_number":0}')$s$,'23514','invalid number denied');
select pg_temp.denied($s$select public.edit_learning_content(current_setting('lessons.course')::uuid,'edit_module_details',current_setting('lessons.module')::uuid,null,(select updated_at from public.course_modules where id=current_setting('lessons.module')::uuid),jsonb_build_object('title','Name','group_type',repeat('x',25),'chapter_number',1))$s$,'23514','invalid type denied');
select pg_temp.denied($s$select public.edit_learning_content(current_setting('lessons.course')::uuid,'edit_module_details',current_setting('lessons.module')::uuid,null,(select updated_at from public.course_modules where id=current_setting('lessons.module')::uuid),jsonb_build_object('title','Name','group_type','Unit','chapter_number',1,'summary',repeat('x',201)))$s$,'23514','summary size enforced');
select pg_temp.claim(5);
select pg_temp.ok((select chapter_number=37 from public.course_modules where id=current_setting('lessons.module')::uuid),'enrolled student reads saved metadata');
select pg_temp.denied($s$select public.edit_learning_content(current_setting('lessons.course')::uuid,'edit_module_details',current_setting('lessons.module')::uuid,null,now(),'{"title":"Forged","group_type":"Unit","chapter_number":1}')$s$,'42501','student metadata edit denied');
select pg_temp.claim(3);
select pg_temp.denied($s$select public.edit_learning_content(current_setting('lessons.course')::uuid,'edit_module_details',current_setting('lessons.module')::uuid,null,now(),'{"title":"Forged","group_type":"Unit","chapter_number":1}')$s$,'42501','foreign tenant metadata edit denied');
reset role;
select pg_temp.ok(not exists((select * from public.lessons except select * from original_lessons) union all (select * from original_lessons except select * from public.lessons)),'chapter edits preserve exact lesson rows');
select pg_temp.ok(not exists((select * from public.lesson_progress except select * from original_progress) union all (select * from original_progress except select * from public.lesson_progress)),'chapter edits preserve exact progress rows');
select count(*) as chapter_metadata_tests from lesson_results;
rollback;
